import type { Chapter, Topic } from "@/lib/study/schema";

/**
 * Algorithms → Greedy; Dynamic programming (CLRS ch. 14–15). Numbers from lib/study/algo2.ts, checked by script:
 * CLRS activities a1…a11 → a1, a4, a8, a11. Fractional knapsack A(10, 60) B(20, 100) C(30, 120), W 50 → 240 (all A, B, 2/3 of C); 0/1 → 220.
 * Huffman a45 b13 c12 d16 e9 f5 → a 0, c 100, b 101, f 1100, e 1101, d 111; 224 bits vs 300 fixed. A5 B9 C12 D13 → 78 bits.
 * Jobs J1(2, 100) J2(1, 19) J3(2, 27) J4(1, 25) J5(3, 15) → slots J3 J1 J5, profit 142.
 * LCS(ABCBDAB, BDCABA) = 4 (BCBA); LCS(AGGTAB, GXTXAYB) = 4 (GTAB). 0/1 knapsack w(1,3,4,5) v(1,4,5,7), W 7 → 9 (items 2, 3).
 * MCM CLRS 30 35 15 5 10 20 25 → 15 125, ((A1(A2A3))((A4A5)A6)); 10 100 5 50 → 7500 (worst 75 000); 10 20 30 40 30 → 30 000.
 * Coins {1,2,5} amount 5: 4 ways, 1 coin; {1,3,4} amount 6: 4 ways, min 2, greedy 3; {2,5,3,6} amount 10: 5 ways.
 * Subset sum {3,34,4,12,5,2}: 9 yes, 30 no. LIS of 10 9 2 5 3 7 101 18 = 4 (2 5 7 101).
 */
